import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
# ---------------------------------------------------------------------------
# Hand written PTX implementing a shared-memory tiled GEMM with thread-level
# register blocking:
#   C(M,N) = A(M,K) * B(K,N)   (row-major, standard PyTorch layout)
#
# CTA tile:  BM=64, BN=64, BK=16
# Block:     8x16 threads (128 threads)
# Each thread computes a 4x8 (TM x TN) register-blocked sub-tile of C,
# staged through shared memory (sA holds a 64x16 tile of A transposed to
# 16x64, sB holds a 16x64 tile of B padded to avoid bank conflicts).
# Profiling of the previous 8x8-blocked kernel showed occupancy limited to
# ~33% by register pressure (128 registers/thread) despite high shared
# memory utilization. Halving the register tile to 4x8 (32 accumulators
# instead of 64) while doubling the CTA thread count to 128 keeps the same
# 64x64 output tile and total shared-memory traffic, but roughly halves
# per-thread register usage, allowing more warps to be resident and
# improving occupancy/latency hiding.
#
# Grid:  (N/64, M/64, 1)
# Block: (8, 16, 1)
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemm_kernel(
    .param .u32 param_M,
    .param .u32 param_N,
    .param .u32 param_K,
    .param .u64 param_A,
    .param .u32 param_lda,
    .param .u64 param_B,
    .param .u32 param_ldb,
    .param .u64 param_C,
    .param .u32 param_ldc
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<200>;
    .reg .b64 %rd<60>;
    .reg .f32 %f<140>;
    .shared .align 16 .b8 sA[4096];
    .shared .align 16 .b8 sB[4352];
    ld.param.u32 %r1, [param_M];
    ld.param.u32 %r2, [param_N];
    ld.param.u32 %r3, [param_K];
    ld.param.u64 %rd1, [param_A];
    ld.param.u32 %r4, [param_lda];
    ld.param.u64 %rd2, [param_B];
    ld.param.u32 %r5, [param_ldb];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r6, [param_ldc];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r10, %tid.x;
    mov.u32 %r11, %tid.y;
    mov.u32 %r12, %ctaid.x;
    mov.u32 %r13, %ctaid.y;
    // row0 = by*64 ; col0 = bx*64
    shl.b32 %r16, %r13, 6;
    shl.b32 %r17, %r12, 6;
    // tid_lin = ty*8 + tx  (0..127)
    shl.b32 %r18, %r11, 3;
    add.s32 %r18, %r18, %r10;
    // localRowBase = ty*4 (TM=4) ; localColBase = tx*8 (TN=8)
    shl.b32 %r19, %r11, 2;
    shl.b32 %r20, %r10, 3;
    mov.u32 %r21, sA;
    mov.u32 %r22, sB;
    mov.f32 %f100, 0f00000000;
    mov.f32 %f101, 0f00000000;
    mov.f32 %f102, 0f00000000;
    mov.f32 %f103, 0f00000000;
    mov.f32 %f104, 0f00000000;
    mov.f32 %f105, 0f00000000;
    mov.f32 %f106, 0f00000000;
    mov.f32 %f107, 0f00000000;
    mov.f32 %f108, 0f00000000;
    mov.f32 %f109, 0f00000000;
    mov.f32 %f110, 0f00000000;
    mov.f32 %f111, 0f00000000;
    mov.f32 %f112, 0f00000000;
    mov.f32 %f113, 0f00000000;
    mov.f32 %f114, 0f00000000;
    mov.f32 %f115, 0f00000000;
    mov.f32 %f116, 0f00000000;
    mov.f32 %f117, 0f00000000;
    mov.f32 %f118, 0f00000000;
    mov.f32 %f119, 0f00000000;
    mov.f32 %f120, 0f00000000;
    mov.f32 %f121, 0f00000000;
    mov.f32 %f122, 0f00000000;
    mov.f32 %f123, 0f00000000;
    mov.f32 %f124, 0f00000000;
    mov.f32 %f125, 0f00000000;
    mov.f32 %f126, 0f00000000;
    mov.f32 %f127, 0f00000000;
    mov.f32 %f128, 0f00000000;
    mov.f32 %f129, 0f00000000;
    mov.f32 %f130, 0f00000000;
    mov.f32 %f131, 0f00000000;
    mov.u32 %r30, 0;   // k0
LOOP_K:
    setp.ge.s32 %p1, %r30, %r3;
    @%p1 bra LOOP_K_END;
    // ---------------- Load A tile: 64x16, vectorized float4, 2 loads/thread (128 threads) ----------------
    add.s32 %r118, %r18, 0;
    shr.u32 %r100, %r118, 2;
