    add.s32 %r118, %r18, 0;
    shr.u32 %r108, %r118, 4;
    and.b32 %r109, %r118, 15;
    shl.b32 %r110, %r109, 2;
    add.s32 %r111, %r30, %r108;
    add.s32 %r112, %r17, %r110;
    mad.lo.s32 %r113, %r111, %r5, %r112;
    mul.wide.s32 %rd22, %r113, 4;
    add.s64 %rd23, %rd2, %rd22;
    ld.global.v4.f32 {%f44, %f45, %f46, %f47}, [%rd23];
    mul.lo.s32 %r115, %r108, 272;
    shl.b32 %r116, %r110, 2;
    add.s32 %r117, %r115, %r116;
    add.s32 %r114, %r22, %r117;
    st.shared.v4.f32 [%r114], {%f44, %f45, %f46, %f47};
    add.s32 %r118, %r18, 128;
    shr.u32 %r108, %r118, 4;
    and.b32 %r109, %r118, 15;
    shl.b32 %r110, %r109, 2;
    add.s32 %r111, %r30, %r108;
    add.s32 %r112, %r17, %r110;
    mad.lo.s32 %r113, %r111, %r5, %r112;
    mul.wide.s32 %rd22, %r113, 4;
    add.s64 %rd23, %rd2, %rd22;
    ld.global.v4.f32 {%f44, %f45, %f46, %f47}, [%rd23];
    mul.lo.s32 %r115, %r108, 272;
    shl.b32 %r116, %r110, 2;
    add.s32 %r117, %r115, %r116;
    add.s32 %r114, %r22, %r117;
    st.shared.v4.f32 [%r114], {%f44, %f45, %f46, %f47};
    bar.sync 0;
    // ---------------- Inner reduction with 4x8 register blocking ----------------
    mov.u32 %r60, 0;
INNER_LOOP:
    setp.ge.s32 %p2, %r60, 16;
    @%p2 bra INNER_END;
    shl.b32 %r180, %r60, 8;
    shl.b32 %r181, %r19, 2;
