    add.s32 %r71, %r70, %r20;
    shl.b32 %r72, %r71, 2;
    add.s32 %r73, %r22, %r72;
    ld.shared.v4.f32 {%f60, %f61, %f62, %f63}, [%r73];
    add.s32 %r74, %r73, 16;
